{
  "name": "opencode-cursor-oauth",
  "version": "0.2.0",
  "description": "OpenCode plugin that connects Cursor's API to OpenCode via OAuth, model discovery, and a local OpenAI-compatible proxy.",
  "license": "MIT",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/v2.d.ts",
      "import": "./dist/v2.js",
      "default": "./dist/v2.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json && node scripts/copy-runtime.mjs",
    "test": "bun test/smoke.ts",
    "prepublishOnly": "npm run build"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ephraimduncan/opencode-cursor.git"
  },
  "homepage": "https://github.com/ephraimduncan/opencode-cursor#readme",
  "bugs": {
    "url": "https://github.com/ephraimduncan/opencode-cursor/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "cursor",
    "oauth",
    "openai-compatible"
  ],
  "engines": {
    "node": ">=18"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@bufbuild/protobuf": "^2.0.0",
    "@opencode-ai/plugin": "0.0.0-beta-17793",
    "@opencode-ai/sdk": "^1.18.9",
    "zod": "^3.24.0"
  },
  "devDependencies": {
    "@types/bun": "^1.3.11",
    "typescript": "^5.9.3"
  }
}
